function overlay(title,desc,button,fn){$('gameOverlay').replaceChildren();const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=desc;const b=document.createElement('button');b.className='primary';b.textContent=button;b.onclick=fn;$('gameOverlay').append(h,p,b);$('gameOverlay').hidden=false;}
function pause(){if(!state?.running||$('quiz').open)return;state.paused=!state.paused;keys.clear();mouseDown=false;$('pause').textContent=state.paused?'Tiếp tục':'Tạm dừng';if(state.paused)overlay('Nghỉ một nhịp','Sẵn sàng khi bạn muốn.','Tiếp tục',pause);else $('gameOverlay').hidden=true;}$('pause').onclick=pause;
window.addEventListener('keydown',e=>{if(page!=='arena'||$('quiz').open)return;const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright','shift'].includes(k))e.preventDefault();if(k==='p'&&!e.repeat)pause();keys.add(k);});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();mouseDown=false;if(state?.running&&!state.paused&&!$('quiz').open)pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state?.running&&!state.paused&&!$('quiz').open)pause();});
function aimPointer(e){const r=canvas.getBoundingClientRect();aim={x:(e.clientX-r.left)*1100/r.width,y:(e.clientY-r.top)*620/r.height};manualAim=false;}
canvas.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'||e.buttons)aimPointer(e);});canvas.addEventListener('pointerdown',e=>{aimPointer(e);canvas.setPointerCapture(e.pointerId);if(e.pointerType==='mouse')mouseDown=true;});window.addEventListener('pointerup',()=>mouseDown=false);window.addEventListener('pointercancel',()=>mouseDown=false);
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);};const release=()=>keys.delete(b.dataset.key);b.onpointerup=release;b.onpointercancel=release;b.onlostpointercapture=release;});
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function burst(x,y,color){for(let i=0;i<12;i++)state.particles.push({x,y,vx:(Math.random()-.5)*180,vy:(Math.random()-.5)*180,life:.55,color});}
function spriteGeometry(m,stage=0,visualScale=1){const im=sprite(m),w0=im.naturalWidth||120,h0=im.naturalHeight||160,scale=Math.min(70/w0,94/h0),w=w0*scale*visualScale*(1+stage*.10),h=h0*scale*visualScale*(1+stage*.05);const r=m.rig||{base:{x:.5,y:.74},tip:{x:.5,y:.0875}};return {w,h,tx:(r.tip.x-.5)*w,ty:(r.tip.y-.5)*h,axis:Math.atan2((r.tip.y-r.base.y)*h,(r.tip.x-r.base.x)*w)};}
function muzzle(e){const g=spriteGeometry(e.m,e.stage||0,e.visualScale||1),rot=e.angle-g.axis;return {x:e.x+g.tx*Math.cos(rot)-g.ty*Math.sin(rot),y:e.y+g.tx*Math.sin(rot)+g.ty*Math.cos(rot)};}
function fire(from,enemy){if(from.cd>0)return;const a=from.angle,tip=muzzle(from);state.bullets.push({x:tip.x,y:tip.y,vx:Math.cos(a)*(enemy?255+state.round*25:470),vy:Math.sin(a)*(enemy?255+state.round*25:470),enemy,life:3});from.cd=enemy?1.1-state.round*.12:.25;}

const questions=[{q:'Một người đã đồng ý nhưng sau đó muốn dừng lại. Bạn nên làm gì?',a:['Dừng lại và tôn trọng quyết định của họ.','Tiếp tục vì họ đã đồng ý trước đó.','Thuyết phục cho đến khi họ đồng ý lại.'],ok:0,ex:lessons[0][1]},{q:'Phát biểu nào đúng về bao cao su?',a:['Loại bỏ hoàn toàn mọi nguy cơ.','Chỉ có tác dụng tránh thai.','Giúp giảm nguy cơ nhiều STI khi dùng đúng và nhất quán.'],ok:2,ex:lessons[2][1]},{q:'Không có triệu chứng có đồng nghĩa là không mắc STI?',a:['Có, chỉ cần nhìn vẻ ngoài.','Không. Nhiều STI có thể không có triệu chứng.','Có, nếu thấy bản thân khỏe.'],ok:1,ex:lessons[3][1]}];
const evolutionNames=['Khởi đầu','Vân năng lượng','Bi giáp','Giáp tinh anh'];
function roundEnd(){state.paused=true;state.p.stage=Math.min(3,state.p.stage+1);$('evolutionNotice').textContent='✦ Tiến hóa '+state.p.stage+'/3 · '+evolutionNames[state.p.stage]+' — thân lớn hơn, ngoại hình mới. Sức mạnh giữ nguyên.';keys.clear();mouseDown=false;const q=questions[state.round-1];$('question').textContent=q.q;$('answers').replaceChildren();$('explanation').textContent='';$('nextRound').hidden=true;q.a.forEach((s,i)=>{const b=document.createElement('button');b.textContent=s;b.onclick=()=>{[...$('answers').children].forEach((x,j)=>{x.disabled=true;if(j===q.ok)x.style.borderColor='#c5f86b';});const correct=i===q.ok;if(correct){state.score+=100;state.correct++;state.p.hp=Math.min(100,state.p.hp+25);}$('explanation').textContent=(correct?'Chính xác! +100 điểm, hồi 25 năng lượng. ':'Chưa đúng. ')+q.ex;$('nextRound').hidden=false;$('nextRound').textContent=state.round===3?'Xem kết quả →':'Sang hiệp tiếp theo →';};$('answers').append(b);});$('quiz').showModal();}
$('quiz').addEventListener('cancel',e=>e.preventDefault());$('nextRound').onclick=()=>{$('quiz').close();if(state.round===3){state.running=false;overlay('Bạn đã hoàn thành!',state.nickname+' · '+state.score+' điểm · '+state.correct+'/3 câu đúng · Tiến hóa: '+evolutionNames[state.p.stage],'Chơi lại',begin);return;}state.round++;state.p.x=240;state.p.y=310;state.p.hp=Math.min(100,state.p.hp+15);state.bot=entity(860,310,models.filter(m=>m.enabled)[state.round%models.filter(m=>m.enabled).length]);state.bullets=[];state.paused=false;state.time=0;canvas.focus();};
function update(dt){const s=state,p=s.p,b=s.bot;s.time+=dt;for(const a of[p,b]){for(const k of['cd','shield','shieldCD','dashCD','hit'])a[k]=Math.max(0,a[k]-dt);}let dx=+keys.has('d')+ +keys.has('arrowright')- +keys.has('a')- +keys.has('arrowleft'),dy=+keys.has('s')+ +keys.has('arrowdown')- +keys.has('w')- +keys.has('arrowup');let l=Math.hypot(dx,dy);if(l){dx/=l;dy/=l;}if(keys.has('shift')&&p.dashCD<=0&&l){p.x+=dx*125;p.y+=dy*125;p.dashCD=3;burst(p.x,p.y,'#c5f86b');}const pg=spriteGeometry(p.m,p.stage,p.visualScale),margin=Math.max(pg.w,pg.h)/2+22;p.x=clamp(p.x+dx*230*dt,margin,1100-margin);p.y=clamp(p.y+dy*230*dt,margin,620-margin);if(keys.has('e')&&p.shieldCD<=0){p.shield=2;p.shieldCD=7;}const turn=+keys.has('r')- +keys.has('q');if(turn){p.angle+=turn*2.6*dt;aim=null;manualAim=true;}else if(!manualAim){const target=aim||b;p.angle=Math.atan2(target.y-p.y,target.x-p.x);}if(keys.has(' ')||mouseDown)fire(p,false);const a=Math.atan2(p.y-b.y,p.x-b.x),d=dist(p,b),approach=d>340?1:d<210?-1:0;b.x=clamp(b.x+(Math.cos(a)*approach*90+Math.cos(a+Math.PI/2)*Math.sin(s.time*1.4)*90)*dt,45,1055);b.y=clamp(b.y+(Math.sin(a)*approach*90+Math.sin(a+Math.PI/2)*Math.sin(s.time*1.4)*90)*dt,55,565);b.angle=Math.atan2(p.y-b.y,p.x-b.x);if(s.time>1)fire(b,true);
for(const shot of s.bullets){shot.x+=shot.vx*dt;shot.y+=shot.vy*dt;shot.life-=dt;const t=shot.enemy?p:b;if(shot.life>0&&dist(shot,t)<30){shot.life=0;if(t.shield<=0){t.hp=Math.max(0,t.hp-(shot.enemy?9:10));t.hit=.12;if(!shot.enemy)s.score+=10;}burst(shot.x,shot.y,shot.enemy?'#b5a1fc':'#c5f86b');}}s.bullets=s.bullets.filter(x=>x.life>0&&x.x>0&&x.x<1100&&x.y>0&&x.y<620);s.particles.forEach(x=>{x.x+=x.vx*dt;x.y+=x.vy*dt;x.life-=dt;});s.particles=s.particles.filter(x=>x.life>0);if(p.hp<=0){s.running=false;overlay('Thử lại một lần nữa?','Bạn đạt '+s.score+' điểm. Dùng E để tạo khiên và Shift để né đòn.','Chơi lại',begin);}else if(b.hp<=0)roundEnd();}
function drawEvolution(e,g){if(!e.stage)return;ctx.save();ctx.rotate(g.axis+Math.PI/2);const extent=Math.min(g.w,g.h);ctx.strokeStyle=e.stage===3?'#ffd68f':'#c5f86b';ctx.lineWidth=1.5;ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=4;for(const side of[-1,1]){ctx.beginPath();ctx.moveTo(side*extent*.09,g.h*.15);ctx.lineTo(side*extent*.15,0);ctx.lineTo(side*extent*.08,-g.h*.16);ctx.stroke();ctx.beginPath();ctx.moveTo(side*extent*.15,0);ctx.lineTo(side*extent*.23,-g.h*.04);ctx.stroke();}ctx.shadowBlur=0;if(e.stage>=2){const total=e.stage===3?6:4;for(let i=0;i<total;i++){const a=(i/total)*Math.PI*2,x=Math.cos(a)*extent*.4,y=Math.sin(a)*extent*.3+g.h*.15;const gr=ctx.createRadialGradient(x-1,y-2,0,x,y,5);gr.addColorStop(0,'#fff');gr.addColorStop(.3,e.stage===3?'#ffd68f':'#c4dce9');gr.addColorStop(1,'#526b77');ctx.fillStyle=gr;ctx.beginPath();ctx.arc(x,y,4.2,0,Math.PI*2);ctx.fill();}}ctx.restore();}
function drawFighter(e,isBot){const im=sprite(e.m),geometry=spriteGeometry(e.m,e.stage||0,e.visualScale||1),labelOffset=Math.max(61,Math.max(geometry.w,geometry.h)/2+15);ctx.save();ctx.translate(e.x,e.y);ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(0,35,30,10,0,0,Math.PI*2);ctx.fill();if(e.shield>0){ctx.strokeStyle='#b9f8ff';ctx.lineWidth=3;ctx.fillStyle='#90efff18';ctx.beginPath();ctx.arc(0,0,Math.max(48,Math.max(geometry.w,geometry.h)/2+8),0,Math.PI*2);ctx.fill();ctx.stroke();}ctx.rotate(e.angle-geometry.axis);ctx.globalAlpha=e.hit>0?.5:1;if(im.complete&&im.naturalWidth)ctx.drawImage(im,-geometry.w/2,-geometry.h/2,geometry.w,geometry.h);drawEvolution(e,geometry);ctx.restore();if(!isBot){const tip=muzzle(e);ctx.strokeStyle='#c5f86b55';ctx.setLineDash([4,5]);ctx.beginPath();ctx.moveTo(tip.x,tip.y);ctx.lineTo(tip.x+Math.cos(e.angle)*90,tip.y+Math.sin(e.angle)*90);ctx.stroke();ctx.setLineDash([]);}ctx.fillStyle='#273d40';ctx.fillRect(e.x-33,e.y-labelOffset,66,5);ctx.fillStyle=isBot?'#b5a1fc':'#c5f86b';ctx.fillRect(e.x-33,e.y-labelOffset,66*e.hp/100,5);ctx.font='11px Arial';ctx.textAlign='center';ctx.fillText(isBot?'MÁY':state.nickname,e.x,e.y+labelOffset+8);}
function draw(){ctx.clearRect(0,0,1100,620);const g=ctx.createRadialGradient(550,310,80,550,310,620);g.addColorStop(0,'#20373b');g.addColorStop(1,'#101a23');ctx.fillStyle=g;ctx.fillRect(0,0,1100,620);ctx.strokeStyle='#a4c4a00c';ctx.lineWidth=1;for(let x=0;x<1100;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,620);ctx.stroke();}for(let y=0;y<620;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(1100,y);ctx.stroke();}ctx.strokeStyle='#68857044';ctx.lineWidth=2;ctx.strokeRect(20,20,1060,580);ctx.beginPath();ctx.ellipse(550,310,260,205,0,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.ellipse(550,310,140,110,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#c5f86b0c';ctx.font='bold 64px Arial';ctx.textAlign='center';ctx.fillText('BODY ARENA',550,330);if(!state)return;drawFighter(state.p,false);drawFighter(state.bot,true);for(const b of state.bullets){ctx.shadowBlur=16;ctx.shadowColor=ctx.fillStyle=b.enemy?'#b5a1fc':'#c5f86b';ctx.beginPath();ctx.arc(b.x,b.y,6,0,Math.PI*2);ctx.fill();}ctx.shadowBlur=0;for(const p of state.particles){ctx.globalAlpha=p.life/.55;ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,4,4);}ctx.globalAlpha=1;$('roundLabel').textContent='Hiệp '+state.round+' / 3 · '+evolutionNames[state.p.stage];$('stats').textContent='Năng lượng '+Math.ceil(state.p.hp)+' / 100  ·  '+state.score+' điểm';$('cooldowns').textContent='Khiên: '+(state.p.shieldCD>0?Math.ceil(state.p.shieldCD)+'s':'Sẵn sàng')+' · Lướt: '+(state.p.dashCD>0?Math.ceil(state.p.dashCD)+'s':'Sẵn sàng');}
function frame(t){const dt=Math.min((t-last)/1000,.035);last=t;if(page==='arena'){if(state?.running&&!state.paused)update(dt);draw();}requestAnimationFrame(frame);}render();let savedScale=100;try{savedScale=Number(localStorage.getItem('bodyArenaScale')||100);}catch{}applyPlayerScale(savedScale);requestAnimationFrame(frame);
